import React from "react";
import { IoWaterOutline } from "react-icons/io5";
import { Func } from "../Hooks/Func";

function Forecast_5day({ CollectSameDate, DailyTemp }) {
  const { get5daysIcon } = Func;

  // 요일 변환
  const ChangeGetDay = ["Sun", "Mon", "Tues", "Wed", "Thu", "Fri", "Sat"];

  return (
    <div className="forecast_5day">
      {DailyTemp.map((value, index) => (
        <div key={index} className="forecast_5day_box">
          <div className="forecast_5day_title">
            <p>{ChangeGetDay[new Date(value.date).getDay()]}</p>
          </div>
          <div className="imgbox">
            <img src={get5daysIcon(CollectSameDate[index])} alt="Icon" />
          </div>
          <div className="forecast_5day_temp">
            <p>H : {value.maxTemp.toFixed(0)}°C</p>
            <p>L : {value.minTemp.toFixed(0)}°C</p>
            <div className="forecast_5day_pop">
              <span>
                <IoWaterOutline />
              </span>
              <p>{(value.avgPOP * 100).toFixed(0)}%</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default Forecast_5day;
