import React from "react";
import Current from "./Page/Current";
import "./Sass/App.scss";
import { useState } from "react";
import { useNavigate } from "react-router-dom";

function App() {
  // Header.js > input 에서 입력된 값을 받아 Current.js로 주기 위함
  // 선택한 도시를 상태로 관리
  const [city, setCity] = useState("");
  // 검색창에 입력한 도시를 상태로 관리
  const [inputCity, setInputCity] = useState("");

  const navigate = useNavigate();

  // 'Enter' 키를 눌렀을 때 실행되는 함수
  const Enter = (e) => {
    if (e.key === "Enter" && inputCity.trim() !== "") {
      setCity(inputCity); // 입력한 도시 이름을 선택
      setInputCity(""); // 입력 후 input 비우기
      navigate("/WeatherForecast");
    }
  };

  // 상태와 상태를 변경하는 함수들을 'Cityfunc' 객체로 묶어 자식 컴포넌트에 전달
  const Cityfunc = {
    city,
    setCity,
    inputCity,
    setInputCity,
    Enter,
  };

  return (
    <div className="wrap">
      <Current Cityfunc={Cityfunc} />
    </div>
  );
}

export default App;
