import React from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faMagnifyingGlass,
  faLocationDot,
  faBuilding,
  faGlobe,
} from "@fortawesome/free-solid-svg-icons";

function Header({ Cityfunc }) {
  // { Cityfunc } 의 필요한 값들을 구조 분해 할당
  const { setCity, inputCity, setInputCity, Enter } = Cityfunc;
  const navigate = useNavigate();

  return (
    <header>
      <div className="searchbar">
        {/* 작성 시 입력한 도시의 값을 inputCity에 반영 */}
        <input
          type="text"
          placeholder="Enter City Name (English)"
          value={inputCity}
          onChange={(e) => setInputCity(e.target.value)}
          onKeyDown={Enter}
        />
        {/* 검색 버튼을 눌렀을 때, 입력한 도시를 선택된 도시로 설정 */}
        <div className="searchbtn">
          <button
            onClick={() => {
              setCity(inputCity); // 입력한 도시 이름을 선택
              setInputCity(""); // 입력 후 input 비우기
              navigate("/WeatherForecast");
            }}
          >
            <FontAwesomeIcon icon={faMagnifyingGlass} />
          </button>
          <button
            onClick={() => {
              setCity(inputCity);
              setInputCity("");
              navigate("/WeatherForecast");
            }}
          >
            <FontAwesomeIcon icon={faLocationDot} />
          </button>

          <button
            onClick={() => {
              navigate("/Domestic");
            }}
          >
            <FontAwesomeIcon icon={faBuilding} />
          </button>

          <button
            onClick={() => {
              navigate("/Global");
            }}
          >
            <FontAwesomeIcon icon={faGlobe} />
          </button>
        </div>
      </div>

      <div className="ham_mobile">
        <button
          onClick={() => {
            setCity(inputCity);
            setInputCity("");
            navigate("/WeatherForecast");
          }}
        >
          <FontAwesomeIcon icon={faLocationDot} />
        </button>

        <button
          onClick={() => {
            navigate("/Domestic");
          }}
        >
          <FontAwesomeIcon icon={faBuilding} />
        </button>

        <button
          onClick={() => {
            navigate("/Global");
          }}
        >
          <FontAwesomeIcon icon={faGlobe} />
        </button>
      </div>
    </header>
  );
}

export default Header;
