import React from "react";
import { Func } from "../Hooks/Func";

function Weather_Sub({ weatherData, forecastData }) {
  const { Feels, getLocalSun } = Func;

  const Daily = Func.getDailyList(forecastData);

  const CollectSameDate = Func.CollectData(forecastData, Daily);

  const DailyTemp = Func.calculateDailyTemp(CollectSameDate);

  return (
    <div className="weather_else">
      <ul className="weather_else_inner">
        <li>{weatherData?.data?.weather[0]?.main}</li>
        <li>
          <img src="/WeatherForecast/img/weather/temp.png" alt="Htemp/Ltemp" />
          <p>
            {DailyTemp[0].maxTemp.toFixed(1)}°C
            <span>/</span>
            {DailyTemp[0].minTemp.toFixed(1)}°C
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/feeltemp.png" alt="feeltemp" />
          <p>{Feels(weatherData)}°C</p>
        </li>
        <li className="del">
          <img src="/WeatherForecast/img/weather/pressure.png" alt="pressure" />
          <p>{weatherData?.data?.main?.pressure}</p>
        </li>
      </ul>
      <ul className="weather_else_inner">
        <li>
          <img src="/WeatherForecast/img/weather/sunrise.png" alt="sunrise" />
          <p>
            {getLocalSun(
              weatherData?.data?.sys?.sunrise,
              weatherData?.data?.timezone
            )}
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/sunset.png" alt="sunset" />
          <p>
            {getLocalSun(
              weatherData?.data?.sys?.sunset,
              weatherData?.data?.timezone
            )}
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/cloud.png" alt="cloud" />
          <p>{weatherData?.data?.clouds?.all}%</p>
        </li>
        <li className="del">
          <img src="/WeatherForecast/img/weather/humidity.png" alt="humidity" />
          <p>{weatherData?.data?.main?.humidity}%</p>
        </li>
      </ul>
      <ul className="weather_else_mobile">
        <li>{weatherData?.data?.weather[0]?.main}</li>
        <li>
          <img src="/WeatherForecast/img/weather/temp.png" alt="Htemp/Ltemp" />
          <p>
            {DailyTemp[0].maxTemp.toFixed(1)}°C
            <span>/</span>
            {DailyTemp[0].minTemp.toFixed(1)}°C
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/feeltemp.png" alt="feeltemp" />
          <p>{Feels(weatherData)}°C</p>
        </li>

        <li>
          <img src="/WeatherForecast/img/weather/sunrise.png" alt="sunrise" />
          <p>
            {getLocalSun(
              weatherData?.data?.sys?.sunrise,
              weatherData?.data?.timezone
            )}
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/sunset.png" alt="sunset" />
          <p>
            {getLocalSun(
              weatherData?.data?.sys?.sunset,
              weatherData?.data?.timezone
            )}
          </p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/cloud.png" alt="cloud" />
          <p>{weatherData?.data?.clouds?.all}%</p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/pressure.png" alt="pressure" />
          <p>{weatherData?.data?.main?.pressure}</p>
        </li>
        <li>
          <img src="/WeatherForecast/img/weather/humidity.png" alt="humidity" />
          <p>{weatherData?.data?.main?.humidity}%</p>
        </li>
      </ul>
    </div>
  );
}

export default Weather_Sub;
