import React from "react";
import CityBox from "../Component_Specific/CityBox";

function Global({ Cityfunc, weatherData }) {
  const { setCity, setInputCity } = Cityfunc;

  const globalcity = [
    {
      name: "7개 주요도시",
      cities: [
        "seoul",
        "tokyo",
        "beijing",
        "new york",
        "london",
        "paris",
        "moscow",
      ],
    },
    {
      name: "아시아 / 오세아니아",
      cities: [
        "osaka",
        "taiwan",
        "bangkok",
        "hongkong",
        "singapore",
        "sydney",
        "wellington",
      ],
    },
    {
      name: "유럽",
      cities: [
        "berlin",
        "rome",
        "madrid",
        "prague",
        "amsterdam",
        "zurich",
        "vienna",
      ],
    },
    {
      name: "북아메리카/남아메리카",
      cities: [
        "los angeles",
        "chicago",
        "miami",
        "toronto",
        "mexico city",
        "sao paulo",
        "buenos aires",
      ],
    },
    {
      name: "중동 / 아프리카",
      cities: [
        "dubai",
        "istanbul",
        "cairo",
        "doha",
        "cape town",
        "casablanca",
        "nairobi",
      ],
    },
  ];

  return (
    <div className="Global">
      <div className="Global_inner">
        {globalcity.map((globalcity, index) => (
          <div key={index} className={`Global_inner_${index + 1}`}>
            <h4>{globalcity.name}</h4>
            <div className="Global_inner_box">
              {globalcity.cities.map((value, index) => (
                <CityBox
                  key={index}
                  value={value}
                  setCity={setCity}
                  setInputCity={setInputCity}
                  weatherData={weatherData}
                />
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Global;
