import React from "react";
import { Func } from "../Hooks/Func";

function Weather_Main({ city, weatherData }) {
  const { Celsius, getIcon } = Func;

  console.log(weatherData.data);
  return (
    <div className="weather">
      {/* 검색한 위치의 날씨를 표시 */}
      <div className="searchbox">
        {/* 검색한 위치의 날씨를 표시 (city가 비지 않은 경우)  */}
        {city !== "" && weatherData?.data && (
          <div className="search_inner">
            <div className="search_img">
              <img
                src={getIcon(weatherData, weatherData?.data?.timezone * 1000)}
                alt="weather"
              />
            </div>
            <div className="search_text">
              <h1>{weatherData?.data.name}</h1>
              <h2>{Celsius(weatherData)} °C</h2>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default Weather_Main;
