import React from "react";
import Weather_Main from "./Weather_Main";
import Weather_Sub from "./Weather_Sub";

function Weather({ Cityfunc, weatherData, forecastData }) {
  return (
    <div className="current_inner">
      <Weather_Main
        Cityfunc={Cityfunc}
        weatherData={weatherData}
        forecastData={forecastData}
      />
      <Weather_Sub weatherData={weatherData} forecastData={forecastData} />
    </div>
  );
}

export default Weather;
