import React from "react";
import Forecast_5day from "./Forecast_5day";
import Forecast_24hour from "./Forecast_24hour";

function Forecast({ CollectSameDate, DailyTemp, forecastData, weatherData }) {
  return (
    <div className="forecast">
      <Forecast_24hour forecastData={forecastData} weatherData={weatherData} />
      <Forecast_5day CollectSameDate={CollectSameDate} DailyTemp={DailyTemp} />
    </div>
  );
}

export default Forecast;
