import React from "react";
import CityBox from "../Component_Specific/CityBox";

function Domestic({ Cityfunc, weatherData }) {
  const { setCity, setInputCity } = Cityfunc;

  // 각 지역별 도시 목록을 객체 배열로 정리
  const koreacity = [
    {
      name: "서울 · 경기",
      cities: [
        "Seoul",
        "Inchon",
        "Suwon",
        "Goyang",
        "Anyang",
        "Seongnam",
        "Yongin",
      ],
    },
    {
      name: "경북 · 경남",
      cities: [
        "Busan",
        "Daegu",
        "Ulsan",
        "Pohang",
        "Changwon",
        "Gimhae",
        "Gumi",
      ],
    },
    {
      name: "강원",
      cities: [
        "Chuncheon",
        "Gangneung",
        "Wonju",
        "Sokcho",
        "Samcheok",
        "Taebaek",
        "Goseong",
      ],
    },
    {
      name: "충남 · 충북",
      cities: [
        "Daejeon",
        "Sejong",
        "Cheongju",
        "Cheonan",
        "Asan",
        "Gongju",
        "Jecheon",
      ],
    },
    {
      name: "전남 · 전북 · 제주",
      cities: [
        "Gwangju",
        "Jeonju",
        "Mokpo",
        "Iksan",
        "Yeosu",
        "Suncheon",
        "Jeju",
      ],
    },
  ];

  return (
    <div className="Domestic">
      <div className="Domestic_inner">
        {koreacity.map((koreacity, index) => (
          <div key={index} className={`Domestic_inner_${index + 1}`}>
            <h4>{koreacity.name}</h4>
            <div className="Domestic_inner_box">
              {koreacity.cities.map((city, index) => (
                <CityBox
                  key={index}
                  value={city}
                  setCity={setCity}
                  setInputCity={setInputCity}
                  weatherData={weatherData}
                />
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Domestic;
