import React, { useEffect, useState } from "react";
import FadeLoader from "react-spinners/FadeLoader";
import { Route, Routes } from "react-router-dom";
import { useWeather } from "../Hooks/useWeather";
import { useForecast } from "../Hooks/useForecast";
import { Func } from "../Hooks/Func";
import Weather from "../Component_Main/Weather";
import Forecast from "../Component_forecast/Forecast";
import Domestic from "./Domestic";
import Domestic_box from "../Component_Specific/Domestic_box";
import Global from "./Global";
import Global_box from "../Component_Specific/Global_box";
import Header from "../Component_Main/Header";

function Current({ Cityfunc }) {
  // { Cityfunc } 의 필요한 값들을 구조 분해 할당
  const { city, setCity, setInputCity } = Cityfunc;

  // 현재 위치의 위도와 경도 상태로 관리
  const [lat, setLat] = useState(null);
  const [lon, setLon] = useState(null);

  // 현재 위치를 가져오는 함수
  const getCurrentLocation = () => {
    navigator.geolocation.getCurrentPosition((value) => {
      let latitude = value.coords.latitude;
      let longitude = value.coords.longitude;
      setLat(latitude);
      setLon(longitude);
    });
  };

  // 컴포넌트가 처음 렌더링될 때 사용자의 현재 위치를 호출
  useEffect(() => {
    getCurrentLocation();
  }, []);

  // useWeather 훅을 사용하여 날씨 데이터 호출
  const weatherData = useWeather(lat, lon, city);

  // useForecast 훅을 사용하여 예보 데이터 호출
  const forecastData = useForecast(lat, lon, city);

  // 로딩 중 표시할 내용
  if (weatherData.isLoading || forecastData.isLoading) {
    return (
      <div className="mainloading">
        <FadeLoader color="black" loading={weatherData.isLoading} size={250} />
      </div>
    );
  }

  // 에러 시 표시할 내용
  if (weatherData.isError || forecastData.isError) {
    alert("입력하신 도시를 찾을 수 없습니다. 도시 이름을 확인 해주세요");
    console.log(weatherData.isError, "weaterdataerror");
    console.log(forecastData.isError, "forecastdataerror");
    setCity("");
    setInputCity("");
  }

  // Daily 데이터 추출
  const Daily = Func.getDailyList(forecastData);

  // 날짜별 예보 데이터 수집
  const CollectSameDate = Func.CollectData(forecastData, Daily);

  // 날짜별 최고기온과 최저기온 계산
  const DailyTemp = Func.calculateDailyTemp(CollectSameDate);

  console.log(weatherData.data);
  return (
    <div className="main">
      <div className="current">
        <Header Cityfunc={Cityfunc} />

        <Routes>
          <Route
            path="/WeatherForecast/"
            element={
              <Weather
                Cityfunc={Cityfunc}
                weatherData={weatherData}
                forecastData={forecastData}
              />
            }
          ></Route>
          <Route path="/Domestic" element={<Domestic_box />}></Route>
          <Route path="/Global" element={<Global_box />}></Route>
        </Routes>
      </div>
      <Routes>
        <Route
          path="/WeatherForecast/"
          element={
            <Forecast
              CollectSameDate={CollectSameDate}
              DailyTemp={DailyTemp}
              forecastData={forecastData}
              weatherData={weatherData}
            />
          }
        ></Route>
        <Route
          path="/Domestic"
          element={<Domestic Cityfunc={Cityfunc} weatherData={weatherData} />}
        ></Route>
        <Route
          path="/Global"
          element={<Global Cityfunc={Cityfunc} weatherData={weatherData} />}
        ></Route>
      </Routes>
    </div>
  );
}

export default Current;
