import React from "react";
import { Func } from "../Hooks/Func";
import { IoWaterOutline } from "react-icons/io5";
function Forecast_24hour({ forecastData, weatherData }) {
  const { get24hoursIcon, getLocalDateTime } = Func;

  return (
    <>
      {forecastData?.data && (
        <div className="forecast_24hr">
          {forecastData?.data?.list?.slice(0, 6).map((value, index) => (
            <div key={index} className="forecast_24hr_box">
              <div className="forecast_24hr_title">
                <p>{getLocalDateTime(value?.dt, weatherData)}</p>
              </div>
              <div className="imgbox">
                <img
                  src={get24hoursIcon(forecastData, value)}
                  alt={value.weather[0].icon}
                />
              </div>
              <p>{(value.main.temp - 273.15).toFixed(0)}°C</p>
              <div className="forecast_24hr_pop">
                <span>
                  <IoWaterOutline />
                </span>
                <p>{(value.pop * 100).toFixed(0)}%</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </>
  );
}

export default Forecast_24hour;
