import { useQuery } from "@tanstack/react-query";
import axios from "axios";

// 현재 위치 날씨 정보를 가져오는 함수
const CurrentLocationWeather = async (latitude, longitude) => {
  const response = await axios.get(
    `https://api.openweathermap.org/data/2.5/weather?lat=${latitude}&lon=${longitude}&appid=1da1cc2e291ce07fae8928171b169c29`
  );
  return response.data;
};

// 도시 이름으로 날씨 정보를 가져오는 함수
const SpecificLocalWeather = async (city) => {
  const response = await axios.get(
    `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=1da1cc2e291ce07fae8928171b169c29`
  );
  return response.data;
};

// 날씨 데이터를 가져오는 훅
export const useWeather = (latitude, longitude, city) => {
  return useQuery({
    queryKey: ["weather", latitude, longitude, city],
    queryFn: () => {
      if (city) {
        return SpecificLocalWeather(city); // 도시명이 있을 경우 해당 도시 날씨 가져오기
      } else if (latitude && longitude) {
        return CurrentLocationWeather(latitude, longitude); // 위치 정보가 있을 경우 위치 기반 날씨 가져오기
      }
      return null; // 둘 다 없으면 null 반환
    },
    retry: 1,
    gcTime: 60 * 1000,
    staleTime: 60 * 60 * 1000,
  });
};
