export const Celsius = (value) => {
  return (value?.data?.main?.temp - 273.15).toFixed(1);
};

export const Feels = (value) => {
  return (value?.data?.main?.feels_like - 273.15).toFixed(1);
};

export const MaxTemp = (value) => {
  return (value?.data?.main?.temp_max - 273.15).toFixed(1);
};

export const MinTemp = (value) => {
  return (value?.data?.main?.temp_min - 273.15).toFixed(1);
};

// 시간대별 아이콘
export const getWeatherIcon = (weather) => {
  const hours = new Date().getHours();

  const isDaytime = hours >= 6 && hours < 18 ? "d" : "n";
  let icon = weather + isDaytime;

  return `/WeatherForecast/img/weather/${icon}.svg`;
};

// 시간대별 아이콘
export const getIcon = (weatherData, timezoneOffset) => {
  const localTime = new Date(
    weatherData?.data?.dt * 1000 - 32400 * 1000 + timezoneOffset
  );
  const hours = localTime.getHours();
  const isDaytime = hours >= 6 && hours < 18 ? "d" : "n";

  const icon = weatherData?.data?.weather[0]?.icon.slice(0, 2) + isDaytime;

  return `/WeatherForecast/img/weather/${icon}.svg`;
};

// 24시간 아이콘
export const get24hoursIcon = (forecastData, value) => {
  const timezoneOffset = forecastData?.data?.city?.timezone * 1000; // 해당 도시의 시간대 (초 단위 , 밀리초 변환)
  const utcTime = value?.dt * 1000; // UTC 기준 시간 (밀리초 변환)
  const localTime = new Date(utcTime - 32400 * 1000 + timezoneOffset); // 현지 시간 적용
  const hours = localTime.getHours(); // 현지 시간의 시간 값 가져오기
  const isDaytime = hours >= 6 && hours < 18 ? "d" : "n";
  let icon = value.weather[0]?.icon.slice(0, 2) + isDaytime;
  return `/WeatherForecast/img/weather/${icon}.svg`;
};

// 5일 아이콘
export const get5daysIcon = (forecast) => {
  const hours = new Date(forecast[0]?.dt_txt).getHours();
  const isDaytime = hours >= 6 && hours < 18 ? "d" : "d";
  // 5일동안 날씨의 기본값을 낮의 날씨로 표기

  const icon = forecast[0]?.weather[0]?.icon.slice(0, 2) + isDaytime;

  return `/WeatherForecast/img/weather/${icon}.svg`;
};

// 일기예보시간대 조정
export const getLocalDateTime = (value, weather) => {
  const localTime = new Date(
    value * 1000 + weather?.data?.timezone * 1000 - 9 * 60 * 60 * 1000
  );
  let hours = localTime.getHours();
  const ampm = hours >= 12 ? "PM" : "AM";

  if (hours === 0) {
    hours = 0;
  }

  if (hours === 12 && ampm === "PM") {
    hours = 12;
  }
  hours = hours > 12 ? hours - 12 : hours;

  return `${hours} ${ampm}`;
};

// 일출,일몰
export const getLocalSun = (value, timezone) => {
  const localTime = new Date(
    value * 1000 + timezone * 1000 - 9 * 60 * 60 * 1000
  );
  const hours = localTime.getHours();
  const minutes = localTime.getMinutes();

  const formattedHours = hours.toString().padStart(2, "0");
  const formattedMinutes = minutes.toString().padStart(2, "0");

  return `${formattedHours} : ${formattedMinutes}`;
};
// forecast>data>list의 정보를 날짜별로 모으기위해 사용
// 날짜별로 고유한 날짜를 저장하는 배열
// Daily에 해당하는 날짜가 없는경우에 추가 (중복제거)
export const getDailyList = (forecastData) => {
  let Daily = [];
  for (let i = 0; i < forecastData?.data?.list?.length; i++) {
    const date = forecastData?.data?.list[i]?.dt_txt.slice(0, 10);
    if (!Daily.includes(date)) {
      Daily.push(date);
    }
  }
  return Daily;
};

// 각 날짜마다 그 날짜에 해당하는 예보 데이터를 모을 배열
// Daily와 dt_txt를 비교하여 일치하면 CollectSameDate[i]에 추가
export const CollectData = (forecastData, Daily) => {
  let CollectSameDate = [[], [], [], [], [], []];
  for (let i = 0; i < Daily.length; i++) {
    for (let j = 0; j < forecastData?.data?.list.length; j++) {
      if (Daily[i] === forecastData?.data?.list[j].dt_txt.slice(0, 10)) {
        CollectSameDate[i].push(forecastData?.data?.list[j]);
      }
    }
  }
  return CollectSameDate;
};

// 날짜별 최고기온과 최저기온을 계산하여 저장
//0번 방의 첫 번째 시간대의 최고기온 , 최저 기온을 당일 최고기온 , 최저 기온으로 설정
export const calculateDailyTemp = (CollectSameDate) => {
  let DailyTemp = [];
  for (let i = 0; i < CollectSameDate.length; i++) {
    let maxTemp = CollectSameDate[i][0]?.main.temp_max;
    let minTemp = CollectSameDate[i][0]?.main.temp_min;
    let allpop = 0;
    let separate = CollectSameDate[i].length;

    // 해당하는 날짜의 모든 시간대를 돌면서 최고기온과 최저기온 호출 및 비교
    for (let j = 1; j < CollectSameDate[i].length; j++) {
      let CompareMaxTemp = CollectSameDate[i][j]?.main.temp_max;
      let CompareMinTemp = CollectSameDate[i][j]?.main.temp_min;
      let ComparePop = CollectSameDate[i][j]?.pop;

      if (CompareMaxTemp > maxTemp) maxTemp = CompareMaxTemp;
      if (CompareMinTemp < minTemp) minTemp = CompareMinTemp;

      allpop += ComparePop;
    }
    let avgPOP = allpop / separate;

    // 날짜별로 최고기온과 최저기온을 DailyTemp에 저장
    DailyTemp.push({
      date: CollectSameDate[i][0]?.dt_txt.slice(0, 10),
      maxTemp: maxTemp - 273.15,
      minTemp: minTemp - 273.15,
      avgPOP: avgPOP,
    });
  }
  return DailyTemp;
};

export const Func = {
  Celsius,
  Feels,
  get24hoursIcon,
  get5daysIcon,
  getLocalDateTime,
  getLocalSun,
  getIcon,
  getDailyList,
  CollectData,
  calculateDailyTemp,
};
