import React from "react";
import FadeLoader from "react-spinners/FadeLoader";
import { useWeather } from "../Hooks/useWeather";
import { Func } from "../Hooks/Func";
import { CiTempHigh } from "react-icons/ci";
import { useNavigate } from "react-router-dom";

function CityBox({ value, setCity, setInputCity }) {
  const navigate = useNavigate();
  const weatherData = useWeather(null, null, value);
  const { Celsius, getIcon } = Func;

  const cityNamesInKorean = {
    // Domestic
    Seoul: "서울",
    Inchon: "인천",
    Suwon: "수원",
    Goyang: "고양",
    Anyang: "안양",
    Seongnam: "성남",
    Yongin: "용인",
    Busan: "부산",
    Daegu: "대구",
    Ulsan: "울산",
    Pohang: "포항",
    Changwon: "창원",
    Gimhae: "김해",
    Gumi: "구미",
    Chuncheon: "춘천",
    Gangneung: "강릉",
    Wonju: "원주",
    Sokcho: "속초",
    Samcheok: "삼척",
    Taebaek: "태백",
    Goseong: "고성",
    Daejeon: "대전",
    Sejong: "세종",
    Cheongju: "청주",
    Cheonan: "천안",
    Asan: "아산",
    Gongju: "공주",
    Jecheon: "제천",
    Gwangju: "광주",
    Jeonju: "전주",
    Mokpo: "목포",
    Iksan: "익산",
    Yeosu: "여수",
    Suncheon: "순천",
    Jeju: "제주",

    // Global
    // Asia
    seoul: "서울",
    tokyo: "도쿄",
    beijing: "베이징",
    "new york": "뉴욕",
    paris: "파리",
    london: "런던",
    moscow: "모스크바",

    // 아시아 ,오세아니아
    osaka: "오사카",
    taiwan: "타이완",
    bangkok: "방콕",
    hongkong: "홍콩",
    singapore: "싱가포르",
    sydney: "시드니",
    wellington: "웰링턴",

    // 유럽
    berlin: "베를린",
    rome: "로마",
    madrid: "마드리드",
    prague: "프라하",
    amsterdam: "암스테르담",
    zurich: "취리히",
    vienna: "비엔나",

    // 북미 , 남미
    "los angeles": "로스앤젤레스",
    chicago: "시카고",
    miami: "마이애미",
    toronto: "토론토",
    "mexico city": "멕시코시티",
    "sao paulo": "상파울루",
    "buenos aires": "부에노스아이레스",

    // 중동 , 아프리카
    dubai: "두바이",
    istanbul: "이스탄불",
    cairo: "카이로",
    doha: "도하",
    "cape town": "케이프타운",
    casablanca: "카사블랑카",
    nairobi: "나이로비",
  };

  // 한국 도시인지 확인 후, 한국 도시일 경우 한국어로 표시
  const cityNameInKorean = cityNamesInKorean[value] || value;

  if (weatherData.isLoading) {
    return <div className="boxloading"></div>;
  }

  // 에러 시 표시할 내용
  if (weatherData.isError) {
    return <p>잠시 후 다시 시도해 주세요. 현재 연결에 문제가 발생했습니다.</p>;
  }

  return (
    <div
      className="CityBox"
      onClick={() => {
        setCity(value);
        setInputCity("");
        navigate("/WeatherForecast");
      }}
    >
      <p>{cityNameInKorean}</p>
      <div className="CityBox_img">
        <img
          src={getIcon(weatherData, weatherData?.data?.timezone * 1000)}
          alt="weather"
        />
      </div>
      <div className="CityBox_temp">
        <span>
          <CiTempHigh />
        </span>
        <p>{Celsius(weatherData)}°C</p>
      </div>
    </div>
  );
}

export default CityBox;
